/// Fetch the contents of the specified inbox folder
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `folder` - The name of the folder to fetch
///
/// Returns
/// * The contents of the inbox folder
pub async fn fetch(
    ctx: &dyn RequestContext,
    folder: &str,
) -> Result<Inbox, Error> {
    let path = "/v1/api/ulv2/inbox/:folder"
        .replace(":folder", folder);
    let res = ctx.get(&path, None, None).await?;
    res.as_slice().try_into().map_err(Error::from)
}

/// Clear the status of all notifications in the specified folder
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `folder` - The name of the folder to clear
pub async fn clear_all_status(
    ctx: &dyn RequestContext,
    folder: &str,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/inbox/:folder"
        .replace(":folder", folder);
    ctx.delete(&path, None, None).await?;
    Ok(())
}

/// Set the status of a notification in the specified folder
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `folder` - The name of the folder to set the status in
/// * `id` - The ID of the notification to set the status for
/// * `status` - The status to set for the notification
pub async fn set_status(
    ctx: &dyn RequestContext,
    folder: &str,
    id: Uuid,
    status: i64,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/inbox/:folder/:id/status/:status"
        .replace(":folder", folder)
        .replace(":id", &id.to_string())
        .replace(":status", &status.to_string());
    let body = Bytes::new();
    ctx.post(&path, body, "text/plain", None, None).await?;
    Ok(())
}

/// Clear the status of a notification in the specified folder
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `folder` - The name of the folder to clear the status in
/// * `id` - The ID of the notification to clear the status for
pub async fn clear_status(
    ctx: &dyn RequestContext,
    folder: &str,
    id: Uuid,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/inbox/:folder/:id"
        .replace(":folder", folder)
        .replace(":id", &id.to_string());
    ctx.delete(&path, None, None).await?;
    Ok(())
}


